/**
 * The vendored cookbook: 165 recipes, their exact drawing code, and the kit
 * that runs them.
 *
 * `manifest.json` is generated by `scripts/build-cookbook.mjs`. The packs stay
 * on disk and are read only when a recipe artifact is rendered, so the plugin
 * does not carry a second copy of every function in memory.
 *
 * @module dsh-artifacts/cookbook
 */

import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

/** Absolute directory of the vendored cookbook. */
export const COOKBOOK_DIR = join(dirname(fileURLToPath(import.meta.url)), '..', 'cookbook');

/** @type {{count: number, families: Record<string, number>, recipes: any[]} | undefined} */
let cachedManifest;

/** @type {Map<string, string>} */
const packCache = new Map();

/**
 * Read and cache the generated manifest.
 * @returns {{count: number, families: Record<string, number>, recipes: any[]}} manifest
 */
export function cookbook() {
  if (cachedManifest === undefined) {
    try {
      cachedManifest = JSON.parse(readFileSync(join(COOKBOOK_DIR, 'manifest.json'), 'utf8'));
    } catch (error) {
      console.warn('[dsh-artifacts] cookbook manifest unavailable:', error instanceof Error ? error.message : error);
      cachedManifest = { count: 0, families: {}, recipes: [] };
    }
  }
  return cachedManifest;
}

/**
 * Every recipe in the cookbook.
 * @returns {any[]} recipes
 */
export function recipes() {
  return cookbook().recipes;
}

/**
 * Family name to recipe count.
 * @returns {Record<string, number>} counts
 */
export function families() {
  return cookbook().families;
}

/**
 * Look up a recipe by id.
 * @param {string} id recipe id
 * @returns {any | undefined} recipe
 */
export function getRecipe(id) {
  return recipes().find((recipe) => recipe.id === id);
}

/**
 * Search the cookbook by id, name, use or family.
 *
 * Ranking: exact id, id prefix, name prefix, then any field. Family filters
 * first, so a query inside a family cannot return a neighbour.
 *
 * @param {{query?: string, family?: string, limit?: number}} [options] search
 * @returns {{total: number, recipes: any[]}} matches
 */
export function searchRecipes(options = {}) {
  const query = typeof options.query === 'string' ? options.query.trim().toLowerCase() : '';
  const family = typeof options.family === 'string' ? options.family.trim().toLowerCase() : '';
  const limit = Number.isInteger(options.limit) && options.limit > 0 ? Math.min(options.limit, 40) : 12;
  const pool = recipes().filter((recipe) => family === '' || recipe.family === family);
  if (query === '') return { total: pool.length, recipes: pool.slice(0, limit) };

  const scored = [];
  for (const recipe of pool) {
    const id = recipe.id.toLowerCase();
    const name = recipe.name.toLowerCase();
    let score = 0;
    if (id === query) score = 100;
    else if (id.startsWith(query)) score = 80;
    else if (name.startsWith(query)) score = 70;
    else if (name.includes(query)) score = 60;
    else if (`${recipe.when} ${recipe.combine} ${recipe.family}`.toLowerCase().includes(query)) score = 40;
    else if (id.includes(query)) score = 30;
    if (score > 0) scored.push({ recipe, score });
  }
  scored.sort((a, b) => b.score - a.score || a.recipe.name.localeCompare(b.recipe.name));
  return { total: scored.length, recipes: scored.slice(0, limit).map((entry) => entry.recipe) };
}

/**
 * Read a recipe pack, cached. The renderer wraps it in its own scope so the
 * pack's top-level helpers stay available to the function that needs them.
 * @param {string} pack pack filename
 * @returns {string} pack source
 */
export function packSource(pack) {
  if (!packCache.has(pack)) packCache.set(pack, readFileSync(join(COOKBOOK_DIR, pack), 'utf8'));
  return packCache.get(pack);
}

/**
 * Read the generated gallery document.
 * @returns {string} HTML
 */
export function gallerySource() {
  return readFileSync(join(COOKBOOK_DIR, 'gallery.html'), 'utf8');
}

/**
 * A recipe id from artifact content: either `"qq"` or `{"id":"qq"}`.
 * @param {string} content artifact content
 * @returns {string | undefined} id
 */
export function recipeIdOf(content) {
  const text = typeof content === 'string' ? content.trim() : '';
  if (text === '') return undefined;
  if (text.startsWith('{')) {
    try {
      const parsed = JSON.parse(text);
      const id = parsed?.id;
      return typeof id === 'string' && /^[a-z][a-z0-9-]*$/u.test(id) ? id : undefined;
    } catch {
      return undefined;
    }
  }
  return /^[a-z][a-z0-9-]*$/u.test(text) ? text : undefined;
}

/**
 * A recipe's Markdown form, used by the md/docx/pptx projections.
 * @param {any} recipe recipe record
 * @returns {string} Markdown
 */
export function recipeMarkdown(recipe) {
  return [
    `# ${recipe.name}`,
    '',
    `**Use it when:** ${recipe.when}`,
    '',
    '## How it is drawn',
    '',
    ...(recipe.steps ?? []).map((step, index) => `${index + 1}. ${step}`),
    '',
    `**Combines with:** ${recipe.combine}`,
    '',
    `Recipe id: \`${recipe.id}\``,
    '',
    '## Code',
    '',
    '```js',
    recipe.code,
    '```',
  ].join('\n');
}
